var SC_REG_BASE={"me":{"ME A1.1":{"title":"The facility provides care in Pregnancy & child birth services","hi":"स्वास्थ्य केंद्र गर्भावस्था और प्रसव से जुड़ी सेवाएँ प्रदान करता है"},"ME A1.2":{"title":"The facility provides Neonatal & Infant Health services","hi":"स्वास्थ्य केंद्र नवजात और शिशु स्वास्थ्य सेवाएँ प्रदान करता है"},"ME A1.3":{"title":"The facility provides Childhood & Adolescent health services","hi":"स्वास्थ्य केंद्र बाल और किशोर स्वास्थ्य सेवाएँ प्रदान करता है"},"ME A1.4":{"title":"The facility provides Family Planning services","hi":"स्वास्थ्य केंद्र परिवार नियोजन सेवाएँ प्रदान करता है"},"ME A1.5":{"title":"The facility provides services for promotion, prevention and treatment of communicable diseases as mandated under National Health Program/state scheme","hi":"स्वास्थ्य केंद्र राष्ट्रीय स्वास्थ्य कार्यक्रम/राज्य योजना के अनुसार संचारी रोगों की रोकथाम, बचाव और उपचार की सेवाएँ प्रदान करता है"},"ME A1.6":{"title":"The facility provide services for acute Simple illness & minor ailments","hi":"स्वास्थ्य केंद्र सामान्य तीव्र बीमारियों और छोटी-मोटी तकलीफ़ों की सेवाएँ प्रदान करता है"},"ME A1.7":{"title":"The facility provides services for promotion, prevention and treatment of Non-communicable diseases as mandated under National Health Program/state scheme","hi":"स्वास्थ्य केंद्र राष्ट्रीय स्वास्थ्य कार्यक्रम/राज्य योजना के अनुसार गैर-संचारी रोगों की रोकथाम, बचाव और उपचार की सेवाएँ प्रदान करता है"},"ME A1.8":{"title":"The facility provides services for common eye ailments","hi":"स्वास्थ्य केंद्र आँखों की सामान्य बीमारियों की सेवाएँ प्रदान करता है"},"ME A1.9":{"title":"The facility provides services for common ENT ailments","hi":"स्वास्थ्य केंद्र कान, नाक, गले (ENT) की सामान्य बीमारियों की सेवाएँ प्रदान करता है"},"ME A1.10":{"title":"The facility provides service for oral health ailments","hi":"स्वास्थ्य केंद्र मुख स्वास्थ्य (दाँत व मुँह) की सेवाएँ प्रदान करता है"},"ME A1.11":{"title":"The facility provide Elderly & Palliative care services","hi":"स्वास्थ्य केंद्र बुज़ुर्गों की देखभाल और प्रशामक (पैलिएटिव) देखभाल सेवाएँ प्रदान करता है"},"ME A1.12":{"title":"The facility provides emergency medical care, including for trauma and burn","hi":"स्वास्थ्य केंद्र आपातकालीन चिकित्सा देखभाल प्रदान करता है, जिसमें चोट और जलने के मामले शामिल हैं"},"ME A1.13":{"title":"The facility provides services for Screening & Management of Mental Health illness","hi":"स्वास्थ्य केंद्र मानसिक स्वास्थ्य की जाँच और प्रबंधन की सेवाएँ प्रदान करता है"},"ME A1.14":{"title":"The facility provides services for health promotion activities & wellness","hi":"स्वास्थ्य केंद्र स्वास्थ्य संवर्धन और वेलनेस गतिविधियों की सेवाएँ प्रदान करता है"},"ME A2.1":{"title":"The facility provides laboratory services as mandated","hi":"स्वास्थ्य केंद्र निर्धारित प्रयोगशाला (लैब) सेवाएँ प्रदान करता है"},"ME A2.2":{"title":"The facility provides services for drug dispensing including medicine refills","hi":"स्वास्थ्य केंद्र दवा वितरण सेवाएँ प्रदान करता है, जिसमें दवाओं की रीफ़िल शामिल है"},"ME B1.1":{"title":"The facility displays its services and entitlements","hi":"स्वास्थ्य केंद्र अपनी सेवाएँ और पात्रताएँ (हक़) प्रदर्शित करता है"},"ME B1.2":{"title":"Patients & visitors are sensitized and educated through appropriate IEC / BCC approaches","hi":"मरीज़ों और आगंतुकों को उपयुक्त IEC/BCC तरीकों से जागरूक और शिक्षित किया जाता है"},"ME B1.3":{"title":"Information about the treatment and entitlements are shared with patients or attendants","hi":"इलाज और पात्रताओं की जानकारी मरीज़ों या उनके परिजनों को दी जाती है"},"ME B2.1":{"title":"The facility is accessible from community and referral centre","hi":"स्वास्थ्य केंद्र समुदाय और रेफ़रल केंद्र से पहुँच में है"},"ME B2.2":{"title":"Access to facility is provided without any physical barrier & friendly to people with disability.","hi":"स्वास्थ्य केंद्र तक पहुँच बिना किसी भौतिक बाधा के है और दिव्यांगजनों के अनुकूल है"},"ME B2.3":{"title":"There is affirmative action to ensure that vulnerable and marginalized sections can access services","hi":"कमज़ोर और वंचित वर्गों तक सेवाएँ पहुँचाने के लिए विशेष कदम उठाए जाते हैं"},"ME B3.1":{"title":"Services are provided in manner that are sensitive to gender religious & cultural need","hi":"सेवाएँ लिंग, धर्म और सांस्कृतिक ज़रूरतों के प्रति संवेदनशील तरीके से दी जाती हैं"},"ME B3.2":{"title":"Staff is aware of Patients rights and responsibilities","hi":"स्टाफ़ मरीज़ों के अधिकारों और ज़िम्मेदारियों से अवगत है"},"ME B3.3":{"title":"The facility has defined and established procedure grievance redressal system in place","hi":"स्वास्थ्य केंद्र में शिकायत निवारण की तय और स्थापित प्रक्रिया है"},"ME B4.1":{"title":"Adequate visual privacy is provided at every point of care","hi":"देखभाल के हर स्थान पर पर्याप्त दृश्य निजता (प्राइवेसी) दी जाती है"},"ME B4.2":{"title":"Confidentiality of patients' records and clinical information is maintained","hi":"मरीज़ों के रिकॉर्ड और चिकित्सा जानकारी की गोपनीयता बनाए रखी जाती है"},"ME B4.3":{"title":"The facility ensures behaviours of its staff is dignified and respectful, while delivering the services","hi":"स्वास्थ्य केंद्र यह सुनिश्चित करता है कि सेवा देते समय स्टाफ़ का व्यवहार सम्मानजनक हो"},"ME B5.1":{"title":"The facility provides free of cost services as per prevalent government schemes/ norms.","hi":"स्वास्थ्य केंद्र प्रचलित सरकारी योजनाओं/मानकों के अनुसार निःशुल्क सेवाएँ देता है"},"ME C1.1":{"title":"Facility has adequate infrastructure, space and amenities as per patient or work load","hi":"स्वास्थ्य केंद्र में मरीज़ों/कार्यभार के अनुसार पर्याप्त भवन, जगह और सुविधाएँ हैं"},"ME C1.2":{"title":"The facility ensures physical safety including electrical and fire safety of infrastructure","hi":"स्वास्थ्य केंद्र भवन की भौतिक सुरक्षा, जिसमें बिजली और आग से सुरक्षा शामिल है, सुनिश्चित करता है"},"ME C1.3":{"title":"The facility ensures availability of information & communication technologies","hi":"स्वास्थ्य केंद्र सूचना और संचार प्रौद्योगिकी (ICT) की उपलब्धता सुनिश्चित करता है"},"ME C2.1":{"title":"The facility ensures availability of Community Health officer","hi":"स्वास्थ्य केंद्र कम्युनिटी हेल्थ ऑफ़िसर (CHO) की उपलब्धता सुनिश्चित करता है"},"ME C2.2":{"title":"The facility have adequate frontline health workers and support staff as requirement","hi":"स्वास्थ्य केंद्र में ज़रूरत के अनुसार पर्याप्त फ़्रंटलाइन स्वास्थ्य कार्यकर्ता और सहायक स्टाफ़ हैं"},"ME C2.3":{"title":"The facility has established procedure for duty roster for facility and community staff","hi":"स्वास्थ्य केंद्र और समुदाय स्टाफ़ के ड्यूटी रोस्टर की स्थापित प्रक्रिया है"},"ME C3.1":{"title":"Competence assessment and performance evaluation of all staff is done on predefined criteria","hi":"सभी स्टाफ़ की दक्षता और कार्य-प्रदर्शन का मूल्यांकन पहले से तय मानदंडों पर होता है"},"ME C3.2":{"title":"The staff is provided training as per defined core competencies and training plan","hi":"स्टाफ़ को तय मुख्य दक्षताओं और प्रशिक्षण योजना के अनुसार प्रशिक्षण दिया जाता है"},"ME C4.1":{"title":"The facility have availability of adequate drugs","hi":"स्वास्थ्य केंद्र में पर्याप्त दवाइयाँ उपलब्ध हैं"},"ME C4.2":{"title":"The facility have adequate consumables as per requirement","hi":"स्वास्थ्य केंद्र में ज़रूरत के अनुसार पर्याप्त उपभोग्य सामग्री (कंज़्यूमेबल) है"},"ME C5.1":{"title":"The facility ensures availability of equipment and instruments for examination and monitoring of patients","hi":"स्वास्थ्य केंद्र मरीज़ों की जाँच और निगरानी के उपकरण व औज़ार उपलब्ध कराता है"},"ME C5.2":{"title":"The facility have adequate furniture and fixture as per service provision","hi":"स्वास्थ्य केंद्र में सेवाओं के अनुसार पर्याप्त फ़र्नीचर और फ़िक्स्चर हैं"},"ME D1.1":{"title":"The facility has established system for infrastructure maintenance","hi":"स्वास्थ्य केंद्र में भवन और ढाँचे के रखरखाव की स्थापित व्यवस्था है"},"ME D1.2":{"title":"The facility has established system for maintaining sanitation and hygiene","hi":"स्वास्थ्य केंद्र में साफ़-सफ़ाई और स्वच्छता बनाए रखने की स्थापित व्यवस्था है"},"ME D2.1":{"title":"There is established procedure for estimation and indenting of drugs and consumables as per requirement","hi":"ज़रूरत के अनुसार दवाओं और सामग्री के आकलन और माँग (इंडेंट) की स्थापित प्रक्रिया है"},"ME D2.2":{"title":"The facility ensures proper storage of drugs and consumables","hi":"स्वास्थ्य केंद्र दवाओं और सामग्री का सही भंडारण सुनिश्चित करता है"},"ME D2.3":{"title":"The facility ensure management of expiry and near expired drugs","hi":"स्वास्थ्य केंद्र एक्सपायर्ड और एक्सपायरी के पास वाली दवाओं का प्रबंधन सुनिश्चित करता है"},"ME D3.1":{"title":"Information regarding ambulatory care & management, public health and managerial functions are recorded and updated through IT platforms","hi":"OPD देखभाल, जन स्वास्थ्य और प्रबंधन से जुड़ी जानकारी IT प्लेटफ़ॉर्म पर दर्ज और अद्यतन की जाती है"},"ME D3.2":{"title":"The facility ensures safe storage, maintenance and retrieval of information & records of services","hi":"स्वास्थ्य केंद्र सेवाओं की जानकारी और रिकॉर्ड का सुरक्षित भंडारण, रखरखाव और पुनः प्राप्ति सुनिश्चित करता है"},"ME D3.3":{"title":"The facility has established procedure for providing consultation using tele medicine","hi":"स्वास्थ्य केंद्र में टेलीमेडिसिन से परामर्श देने की स्थापित प्रक्रिया है"},"ME D4.1":{"title":"The facility has established procedure for management of activities of Jan Arogya Samiti","hi":"स्वास्थ्य केंद्र में जन आरोग्य समिति (JAS) की गतिविधियों के प्रबंधन की स्थापित प्रक्रिया है"},"ME D4.2":{"title":"The facility has established procedures for community based monitoring of its services through social audits","hi":"स्वास्थ्य केंद्र में सामाजिक अंकेक्षण (सोशल ऑडिट) से सेवाओं की सामुदायिक निगरानी की स्थापित प्रक्रिया है"},"ME D4.3":{"title":"The facility has established procedure for supporting and monitoring activities of Community health workers","hi":"स्वास्थ्य केंद्र में सामुदायिक स्वास्थ्य कार्यकर्ताओं की गतिविधियों में सहायता और निगरानी की स्थापित प्रक्रिया है"},"ME D5.1":{"title":"The Ayushman Arogya Mandir facilitate planning & implementation of health promotion and disease prevention activities through community level interventions","hi":"आयुष्मान आरोग्य मंदिर सामुदायिक स्तर के प्रयासों से स्वास्थ्य संवर्धन और रोग-रोकथाम गतिविधियों की योजना और क्रियान्वयन में मदद करता है"},"ME D5.2":{"title":"The facility has Patient Support Groups(PSG) as per the issues/ diseases in its catering population","hi":"स्वास्थ्य केंद्र में अपनी आबादी की समस्याओं/बीमारियों के अनुसार मरीज़ सहायता समूह (PSG) हैं"},"ME D5.3":{"title":"The facility ensure multisectoral convergence for health promotion and primary prevention","hi":"स्वास्थ्य केंद्र स्वास्थ्य संवर्धन और प्राथमिक रोकथाम के लिए बहु-क्षेत्रीय तालमेल सुनिश्चित करता है"},"ME D6.1":{"title":"The facility ensures its processes are in compliance with statutory and legal requirement","hi":"स्वास्थ्य केंद्र सुनिश्चित करता है कि उसकी प्रक्रियाएँ वैधानिक और क़ानूनी आवश्यकताओं के अनुरूप हैं"},"ME E1.1":{"title":"The facility has established procedure for empanelment & registration of individual and families","hi":"स्वास्थ्य केंद्र में व्यक्तियों और परिवारों के पंजीकरण (एम्पैनलमेंट) की स्थापित प्रक्रिया है"},"ME E1.2":{"title":"The facility has established procedure for registration & consultation in Ayushman Arogya Mandir","hi":"आयुष्मान आरोग्य मंदिर में पंजीकरण और परामर्श की स्थापित प्रक्रिया है"},"ME E1.3":{"title":"The facility has established procedure for follow up/ re-assessment of patients","hi":"स्वास्थ्य केंद्र में मरीज़ों के फ़ॉलो-अप/पुनर्मूल्यांकन की स्थापित प्रक्रिया है"},"ME E2.1":{"title":"The facility has established procedure for continuity of care","hi":"स्वास्थ्य केंद्र में देखभाल की निरंतरता की स्थापित प्रक्रिया है"},"ME E2.2":{"title":"The facility has established procedure for undertaking referred in & referred out of the cases","hi":"स्वास्थ्य केंद्र में मरीज़ों को रेफ़र करने और रेफ़र होकर आए मरीज़ों की स्थापित प्रक्रिया है"},"ME E3.1":{"title":"The facility has established procedure for laboratory diagnosis as per guidelines","hi":"स्वास्थ्य केंद्र में दिशानिर्देशों के अनुसार लैब जाँच की स्थापित प्रक्रिया है"},"ME E4.1":{"title":"Facility follows protocols for safe drug administration","hi":"स्वास्थ्य केंद्र सुरक्षित दवा देने के प्रोटोकॉल का पालन करता है"},"ME E4.2":{"title":"There is process for identifying and cautious administration of high alert drugs","hi":"हाई-अलर्ट दवाओं की पहचान और सावधानी से देने की प्रक्रिया है"},"ME E5.1":{"title":"There is procedure of rational use of drugs","hi":"दवाओं के तर्कसंगत उपयोग की प्रक्रिया है"},"ME E5.2":{"title":"Facility has system in place to periodically monitor the treatment provided by CHO","hi":"CHO द्वारा दिए गए इलाज की समय-समय पर निगरानी की व्यवस्था है"},"ME E6.1":{"title":"There is established procedure for identification & periodic monitoring of the patients","hi":"मरीज़ों की पहचान और समय-समय पर निगरानी की स्थापित प्रक्रिया है"},"ME E6.2":{"title":"Prescribed treatment plan and procedure performed are recorded in patient's record","hi":"तय इलाज योजना और की गई प्रक्रिया मरीज़ के रिकॉर्ड में दर्ज की जाती है"},"ME E6.3":{"title":"Adequate forms, formats and records are available as per services mandate","hi":"सेवाओं के अनुसार पर्याप्त फ़ॉर्म, प्रारूप और रिकॉर्ड उपलब्ध हैं"},"ME E7.1":{"title":"Emergency protocols are defined and implemented","hi":"आपातकालीन प्रोटोकॉल तय और लागू हैं"},"ME E7.2":{"title":"The facility has disaster management plan in place","hi":"स्वास्थ्य केंद्र में आपदा प्रबंधन योजना है"},"ME E8.1":{"title":"The facility provides services for Ophthalmic ailments including blindness and refractive errors as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार अंधापन और दृष्टि दोष सहित आँखों की बीमारियों की सेवाएँ देता है"},"ME E8.2":{"title":"The facility provides services for ENT ailments as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार ENT बीमारियों की सेवाएँ देता है"},"ME E8.3":{"title":"The facility provides service for oral health ailments","hi":"स्वास्थ्य केंद्र मुख स्वास्थ्य समस्याओं की सेवाएँ देता है"},"ME E9.1":{"title":"The facility provides services under mental health Program as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार मानसिक स्वास्थ्य कार्यक्रम की सेवाएँ देता है"},"ME E10.1":{"title":"The facility provides services under National vector Borne disease control programme as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार राष्ट्रीय वेक्टर जनित रोग नियंत्रण कार्यक्रम (NVBDCP) की सेवाएँ देता है"},"ME E10.2":{"title":"The facility provides services under National Tuberculosis Elimination Program (NTEP)","hi":"स्वास्थ्य केंद्र राष्ट्रीय क्षय रोग उन्मूलन कार्यक्रम (NTEP) की सेवाएँ देता है"},"ME E10.3":{"title":"The facility provides services under National Leprosy Eradication Program as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार राष्ट्रीय कुष्ठ उन्मूलन कार्यक्रम (NLEP) की सेवाएँ देता है"},"ME E10.4":{"title":"The facility provides services under National AIDS Control Program as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार राष्ट्रीय एड्स नियंत्रण कार्यक्रम (NACP) की सेवाएँ देता है"},"ME E10.5":{"title":"The facility provides services under Integrate Disease surveillance as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार एकीकृत रोग निगरानी (IDSP) की सेवाएँ देता है"},"ME E10.6":{"title":"The facilities provide services for National Viral Hepatitis Control Programme (NVHCP)","hi":"स्वास्थ्य केंद्र राष्ट्रीय वायरल हेपेटाइटिस नियंत्रण कार्यक्रम (NVHCP) की सेवाएँ देता है"},"ME E11.1":{"title":"The facility provides services for hypertension as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार उच्च रक्तचाप (हाइपरटेंशन) की सेवाएँ देता है"},"ME E11.2":{"title":"The facility provides services for Diabetes as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार मधुमेह (डायबिटीज़) की सेवाएँ देता है"},"ME E11.3":{"title":"The facility provides services for cancer screening and referral as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार कैंसर स्क्रीनिंग और रेफ़रल सेवाएँ देता है"},"ME E11.4":{"title":"The facility provides services for de addiction, and locally prevalent health diseases as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार नशामुक्ति और स्थानीय रूप से प्रचलित रोगों की सेवाएँ देता है"},"ME E11.5":{"title":"The facility promotes services for health & wellness","hi":"स्वास्थ्य केंद्र स्वास्थ्य और वेलनेस सेवाओं को बढ़ावा देता है"},"ME E12.1":{"title":"The facility provides services for elderly Care as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार बुज़ुर्गों की देखभाल सेवाएँ देता है"},"ME E12.2":{"title":"The facility provides services for Palliative care as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार प्रशामक (पैलिएटिव) देखभाल सेवाएँ देता है"},"ME E13.1":{"title":"Post natal visit & counselling for new born & infant care is provided as per guideline","hi":"दिशानिर्देशों के अनुसार नवजात और शिशु देखभाल के लिए प्रसवोत्तर भेंट और परामर्श दिया जाता है"},"ME E13.2":{"title":"The facility provides immunization services as per guideline","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार टीकाकरण सेवाएँ देता है"},"ME E13.3":{"title":"Management of children for ARI, diarrhoea, malnutrition and other illness","hi":"बच्चों में ARI, दस्त, कुपोषण और अन्य बीमारियों का प्रबंधन"},"ME E14.1":{"title":"Family planning counselling services are provided as per guidelines","hi":"दिशानिर्देशों के अनुसार परिवार नियोजन परामर्श सेवाएँ दी जाती हैं"},"ME E14.2":{"title":"The facility provides spacing methods for family planning as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार परिवार नियोजन के अंतराल (स्पेसिंग) तरीके देता है"},"ME E14.3":{"title":"The facility provides limiting methods for family planning as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार परिवार नियोजन के स्थायी (लिमिटिंग) तरीके देता है"},"ME E15.1":{"title":"The facility provides promotive, preventive & curative service for adolescent","hi":"स्वास्थ्य केंद्र किशोरों के लिए संवर्धन, बचाव और उपचार सेवाएँ देता है"},"ME E16.1":{"title":"There is an established procedure for registration and follow up of pregnant women.","hi":"गर्भवती महिलाओं के पंजीकरण और फ़ॉलो-अप की स्थापित प्रक्रिया है"},"ME E16.2":{"title":"There is an established procedure for History taking, Physical examination, and counselling of each antenatal woman, visiting the facility.","hi":"स्वास्थ्य केंद्र में आने वाली हर गर्भवती महिला के इतिहास, शारीरिक जाँच और परामर्श की स्थापित प्रक्रिया है"},"ME E16.3":{"title":"The facility ensures of drugs & diagnostics are prescribed as per protocol","hi":"स्वास्थ्य केंद्र सुनिश्चित करता है कि दवाएँ और जाँचें प्रोटोकॉल के अनुसार लिखी जाएँ"},"ME E16.4":{"title":"There is an established procedure for identification of High risk pregnancy and appropriate & timely referral.","hi":"हाई-रिस्क गर्भावस्था की पहचान और उचित व समय पर रेफ़रल की स्थापित प्रक्रिया है"},"ME E16.5":{"title":"Counselling of pregnant women is done as per standard protocol and gestational age","hi":"गर्भवती महिलाओं का परामर्श मानक प्रोटोकॉल और गर्भावस्था की अवधि के अनुसार होता है"},"ME E17.1":{"title":"Established procedures and standard protocols for management of different stages of labour including AMTSL (Active Management of third Stage of labour) are followed at the facility","hi":"स्वास्थ्य केंद्र में AMTSL सहित प्रसव के विभिन्न चरणों के प्रबंधन की स्थापित प्रक्रियाएँ और मानक प्रोटोकॉल अपनाए जाते हैं"},"ME E17.2":{"title":"Facility staff adheres to standard procedures for routine care of new-born immediately after birth and new born resuscitation","hi":"स्टाफ़ जन्म के तुरंत बाद नवजात की नियमित देखभाल और नवजात पुनर्जीवन की मानक प्रक्रियाओं का पालन करता है"},"ME E17.3":{"title":"There is established procedure for management/Referral of Obstetrics Emergencies as per scope of services.","hi":"सेवाओं के दायरे के अनुसार प्रसूति आपात स्थितियों के प्रबंधन/रेफ़रल की स्थापित प्रक्रिया है"},"ME E18.1":{"title":"Post partum Care is provided to the mothers","hi":"माँ को प्रसवोत्तर देखभाल दी जाती है"},"ME E18.2":{"title":"There is a established procedures for Postnatal visits & counselling of Mother and Child","hi":"माँ और बच्चे की प्रसवोत्तर भेंट और परामर्श की स्थापित प्रक्रिया है"},"ME F1.1":{"title":"Facility ensures that staff is working as team and monitor the infection control practices","hi":"स्वास्थ्य केंद्र सुनिश्चित करता है कि स्टाफ़ टीम के रूप में काम करे और संक्रमण नियंत्रण की प्रथाओं की निगरानी करे"},"ME F2.1":{"title":"Hand Hygiene facilities are provided at point of use & ensures adherence to standard practices","hi":"हाथ स्वच्छता की सुविधाएँ उपयोग के स्थान पर उपलब्ध हैं और मानक प्रथाओं का पालन सुनिश्चित है"},"ME F3.1":{"title":"The facility ensures availability of personal protection equipment and ensures adherence to standard practices","hi":"स्वास्थ्य केंद्र व्यक्तिगत सुरक्षा उपकरण (PPE) की उपलब्धता और मानक प्रथाओं का पालन सुनिश्चित करता है"},"ME F4.1":{"title":"The facility ensures availability of material and adherence to Standard Practices for decontamination and cleaning of instruments and followed by procedure/ patient care areas.","hi":"स्वास्थ्य केंद्र औज़ारों और फिर प्रक्रिया/मरीज़ देखभाल क्षेत्रों के कीटाणुशोधन और सफ़ाई की सामग्री और मानक प्रथाएँ सुनिश्चित करता है"},"ME F4.2":{"title":"The facility ensures standard practices and materials for disinfection and sterilization of instruments and equipment","hi":"स्वास्थ्य केंद्र औज़ारों और उपकरणों के विसंक्रमण (डिसइन्फ़ेक्शन) और स्टेरिलाइज़ेशन की मानक प्रथाएँ और सामग्री सुनिश्चित करता है"},"ME F5.1":{"title":"The facility ensures segregation and storage of Bio Medical Waste as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार बायोमेडिकल कचरे का पृथक्करण और भंडारण सुनिश्चित करता है"},"ME F5.2":{"title":"The facility ensures management of sharps as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार नुकीली वस्तुओं (शार्प्स) का प्रबंधन सुनिश्चित करता है"},"ME F5.3":{"title":"The facility ensures management of hazardous & general waste","hi":"स्वास्थ्य केंद्र ख़तरनाक और सामान्य कचरे का प्रबंधन सुनिश्चित करता है"},"ME F5.4":{"title":"The facility ensures transportation & disposal of waste as per guidelines","hi":"स्वास्थ्य केंद्र दिशानिर्देशों के अनुसार कचरे का परिवहन और निपटान सुनिश्चित करता है"},"ME G1.1":{"title":"The facility has a quality improvement team and it review its quality activities at periodic intervals","hi":"स्वास्थ्य केंद्र में गुणवत्ता सुधार टीम है और वह समय-समय पर अपनी गुणवत्ता गतिविधियों की समीक्षा करती है"},"ME G2.1":{"title":"The facility ensures mechanism for conducting patient satisfaction survey","hi":"स्वास्थ्य केंद्र में मरीज़ संतुष्टि सर्वे करने की व्यवस्था है"},"ME G3.1":{"title":"Updated work instructions for all key clinical processes are available","hi":"सभी मुख्य चिकित्सा प्रक्रियाओं के अद्यतन कार्य निर्देश (WI) उपलब्ध हैं"},"ME G4.1":{"title":"Handholding support and supervision is provided to Ayushman Arogya Mandir by PHC, block/ district/state teams","hi":"PHC, ब्लॉक/ज़िला/राज्य टीमों द्वारा आयुष्मान आरोग्य मंदिर को सहयोग और पर्यवेक्षण दिया जाता है"},"ME G4.2":{"title":"The facility conducts periodic internal assessment","hi":"स्वास्थ्य केंद्र समय-समय पर आंतरिक मूल्यांकन करता है"},"ME G4.3":{"title":"The facility ensures non compliances are recorded adequately and action plan is made on the gaps found in the assessment/review process using quality improvement methods","hi":"स्वास्थ्य केंद्र सुनिश्चित करता है कि ग़ैर-अनुपालन ठीक से दर्ज हों और मूल्यांकन/समीक्षा में पाई कमियों पर गुणवत्ता सुधार तरीकों से कार्य योजना बने"},"ME G5.1":{"title":"The facility has defined Quality policy and quality objectives","hi":"स्वास्थ्य केंद्र की गुणवत्ता नीति और गुणवत्ता उद्देश्य तय हैं"},"ME H1.1":{"title":"The facility measures productivity indicators services on monthly basis","hi":"स्वास्थ्य केंद्र हर महीने उत्पादकता संकेतकों को मापता है"},"ME H2.1":{"title":"The facility measures efficiency indicators on monthly basis","hi":"स्वास्थ्य केंद्र हर महीने दक्षता संकेतकों को मापता है"},"ME H3.1":{"title":"The facility measures clinical care indicators on monthly basis","hi":"स्वास्थ्य केंद्र हर महीने चिकित्सा देखभाल संकेतकों को मापता है"},"ME H4.1":{"title":"The facility measures service quality indicators on monthly basis","hi":"स्वास्थ्य केंद्र हर महीने सेवा गुणवत्ता संकेतकों को मापता है"}}};
